179	static time_t mooncat_monotonic_seconds(void)
180	{
181	    struct timespec now;
182	
183	    if (clock_gettime(CLOCK_MONOTONIC, &now) != 0) {
184	        return 0;
185	    }
186	
187	    return now.tv_sec;
188	}
