190	static uint32_t mooncat_cooldown_remaining(
191	    const struct mooncat_coach_decision_s *decision, time_t now)
192	{
193	    time_t elapsed;
194	
195	    if (g_mooncat_last_delivery_monotonic <= 0 || now <= 0) {
196	        return 0;
197	    }
198	
199	    if (now < g_mooncat_last_delivery_monotonic) {
200	        g_mooncat_last_delivery_monotonic = 0;
201	        return 0;
202	    }
203	
204	    elapsed = now - g_mooncat_last_delivery_monotonic;
205	    if ((uint64_t)elapsed >= decision->cooldown_seconds) {
206	        return 0;
207	    }
208	
209	    return decision->cooldown_seconds - (uint32_t)elapsed;
210	}
