212	int tool_mooncat_coach_execute(const char *input_json, char *output,
213	                               size_t output_size)
214	{
215	    struct mooncat_coach_observation_s observation = {0};
216	    struct mooncat_coach_decision_s decision;
217	    cJSON *input;
218	    cJSON *result;
219	    const char *mode = NULL;
220	    char error[64] = "";
221	    char notification[192] = "";
222	    bool delivered = false;
223	    uint32_t remaining = 0;
224	    int status = OK;
225	
226	    if (!output || output_size == 0) {
227	        return ERROR;
228	    }
229	
230	    input = cJSON_Parse(input_json ? input_json : "{}");
231	    if (!input || !cJSON_IsObject(input)) {
232	        cJSON_Delete(input);
233	        snprintf(output, output_size,
234	                 "{\"ok\":false,\"error\":\"invalid_json\"}");
235	        return ERROR;
236	    }
237	
238	    if (mooncat_parse_observation(input, &observation, &mode,
239	                                  error, sizeof(error)) != OK) {
240	        cJSON_Delete(input);
241	        snprintf(output, output_size,
242	                 "{\"ok\":false,\"error\":\"%s\"}", error);
243	        return ERROR;
244	    }
245	
246	    decision = mooncat_coach_evaluate(&observation);
247	    if (decision.action != MOONCAT_COACH_NONE &&
248	        mooncat_coach_format_notification(&observation, &decision,
249	                                           notification,
250	                                           sizeof(notification)) != 0) {
251	        cJSON_Delete(input);
252	        snprintf(output, output_size,
253	                 "{\"ok\":false,\"error\":\"notification_format_failed\"}");
254	        return ERROR;
255	    }
256	
257	    if (decision.action != MOONCAT_COACH_NONE &&
258	        strcmp(mode, "execute") == 0) {
259	        agent_msg_t message = {0};
260	        time_t now = mooncat_monotonic_seconds();
261	
262	        pthread_mutex_lock(&g_mooncat_cooldown_lock);
263	        if (now <= 0) {
264	            snprintf(error, sizeof(error), "monotonic_clock_unavailable");
265	            status = ERROR;
266	        } else {
267	            remaining = mooncat_cooldown_remaining(&decision, now);
268	        }
269	        if (status == OK && remaining == 0) {
270	            strncpy(message.channel, MOONCAT_CHANNEL,
271	                    sizeof(message.channel) - 1);
272	            strncpy(message.chat_id, MOONCAT_CHAT_ID,
273	                    sizeof(message.chat_id) - 1);
274	            message.content = strdup(notification);
275	            if (!message.content ||
276	                message_bus_push_outbound(&message) != OK) {
277	                free(message.content);
278	                message.content = NULL;
279	                snprintf(error, sizeof(error), "message_bus_push_failed");
280	                status = ERROR;
281	            } else {
282	                g_mooncat_last_delivery_monotonic = now;
283	                delivered = true;
284	            }
285	        }
286	        pthread_mutex_unlock(&g_mooncat_cooldown_lock);
287	    }
288	
289	    result = cJSON_CreateObject();
290	    if (!result) {
291	        cJSON_Delete(input);
292	        snprintf(output, output_size,
293	                 "{\"ok\":false,\"error\":\"allocation_failed\"}");
294	        return ERROR;
295	    }
296	
297	    cJSON_AddBoolToObject(result, "ok", status == OK);
298	    cJSON_AddStringToObject(result, "status",
299	        status != OK ? "error" :
300	        delivered ? "delivered" :
301	        (decision.action == MOONCAT_COACH_NONE || remaining > 0) ?
302	            "noop" : "preview");
303	    cJSON_AddStringToObject(result, "source",
304	                           mooncat_source_name(observation.source));
305	    cJSON_AddStringToObject(result, "evidence_boundary",
306	        observation.source == MOONCAT_DATA_SOURCE_SIMULATED ?
307	            "demo_only_not_physical_sensor" :
308	            "live_source_not_verified");
309	    cJSON_AddStringToObject(result, "mode", mode);
310	    cJSON_AddStringToObject(result, "action",
311	                           mooncat_coach_action_name(decision.action));
312	    cJSON_AddStringToObject(result, "priority",
313	                           mooncat_priority_name(decision.priority));
314	    cJSON_AddStringToObject(result, "reason_id",
315	                           remaining > 0 ? "cooldown_active" :
316	                           decision.reason_id);
317	    cJSON_AddStringToObject(result, "policy_reason_id", decision.reason_id);
318	    cJSON_AddNumberToObject(result, "duration_seconds",
319	                            decision.suggested_duration_seconds);
320	    cJSON_AddNumberToObject(result, "cooldown_seconds",
321	                            decision.cooldown_seconds);
322	    cJSON_AddNumberToObject(result, "cooldown_remaining_seconds", remaining);
323	    cJSON_AddBoolToObject(result, "delivered", delivered);
324	    cJSON_AddStringToObject(result, "channel", MOONCAT_CHANNEL);
325	    if (notification[0] != '\0') {
326	        cJSON_AddStringToObject(result, "notification", notification);
327	    }
328	    if (error[0] != '\0') {
329	        cJSON_AddStringToObject(result, "error", error);
330	    }
331	
332	    cJSON_Delete(input);
333	    if (mooncat_write_json(result, output, output_size) != OK) {
334	        cJSON_Delete(result);
335	        return ERROR;
336	    }
337	    cJSON_Delete(result);
338	    return status;
339	}
