55	    const unsigned char *p = *cursor;
56	    uint32_t codepoint;
57	    size_t remaining = (size_t)(end - p);
58	
59	    if (*p < 0x80) {
60	        *cursor = p + 1;
61	        return *p;
62	    }
63	
64	    if (remaining >= 2 && (*p & 0xe0) == 0xc0 &&
65	        (p[1] & 0xc0) == 0x80) {
66	        codepoint = ((uint32_t)(p[0] & 0x1f) << 6) | (p[1] & 0x3f);
67	        *cursor = p + 2;
68	        return codepoint >= 0x80 ? codepoint : UINT32_C(0xfffd);
69	    }
70	
71	    if (remaining >= 3 && (*p & 0xf0) == 0xe0 &&
72	        (p[1] & 0xc0) == 0x80 && (p[2] & 0xc0) == 0x80) {
73	        codepoint = ((uint32_t)(p[0] & 0x0f) << 12) |
74	                    ((uint32_t)(p[1] & 0x3f) << 6) | (p[2] & 0x3f);
75	        *cursor = p + 3;
76	        return codepoint >= 0x800 &&
