98	void mooncat_router_featurize(const char *text, uint8_t *features,
99	                              size_t feature_count)
100	{
101	    const unsigned char *cursor = (const unsigned char *)(text ? text : "");
102	    const unsigned char *end = cursor + strlen((const char *)cursor);
103	    uint32_t previous = 0;
104	    bool has_previous = false;
105	    bool previous_was_digit = false;
106	    size_t seen = 0;
107	
108	    if (!features || feature_count == 0) {
109	        return;
110	    }
111	
112	    memset(features, 0, feature_count);
113	    while (*cursor != '\0' && seen < 1024) {
114	        uint32_t codepoint = mooncat_utf8_next(&cursor, end);
115	
116	        if (codepoint >= 'A' && codepoint <= 'Z') {
117	            codepoint += 'a' - 'A';
118	        }
119	        if (codepoint <= 0x20) {
120	            previous_was_digit = false;
121	            continue;
122	        }
123	
124	        bool is_digit =
125	            (codepoint >= '0' && codepoint <= '9') ||
126	            (codepoint >= 0xff10 && codepoint <= 0xff19);
127	        if (is_digit) {
128	            if (previous_was_digit) {
129	                continue;
130	            }
131	            codepoint = MOONCAT_ROUTER_NUMBER_SENTINEL;
132	        }
133	        previous_was_digit = is_digit;
134	
135	        features[mooncat_hash_gram(0x11, codepoint, 0, false) %
136	                 feature_count] = 1;
137	        if (has_previous) {
138	            features[mooncat_hash_gram(0x22, previous, codepoint, true) %
139	                     feature_count] = 1;
140	        }
141	        previous = codepoint;
142	        has_previous = true;
143	        seen++;
144	    }
145	}
